# Code generated by Claude
"""
Split diagnosis of the moved layout's place failure at OVER (David 2026-10-25, overnight step 2). Measurement only: nothing in src/ or any setting is changed.

The same selection and episode as stance_select_moved_test.py (task_cfg MOVED, stance mode bench_region). A test source records, during the first OVER of the place (segment 4/4):
  b. the hand's smallest distance to the hotplate (the left arm's links 3 to 7, hand and fingers against the hotplate's geoms; the held beaker is not in the group), against the 8 mm limit;
  c. per joint, the commanded angle (the arm's q_cmd) against the measured one, and the commanded angle's distance to the solver's own bounds (the joint limit minus the 10 degree margin);
and keeps the state at the first tick of OVER and at its last tick. After the episode, on scratch copies of that state:
  a. the arm's own IK (MinkArm, the same settings) solved on the OVER target many times over: the best position and rotation error it reaches; and the same with the collision avoidance off, with the joint margin 0,
     and with both off, to see which constraint holds the arm;
  d. at the last tick: the joint speed the solver asks for, with each constraint set (all on / collision off / margin 0 / both off).

    MUJOCO_GL=egl python experiments/moved_place_split_diag.py
"""
import copy
import json
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mink  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.mink_arm import MinkArm  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import MINK_CFG  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402

VARIANTS = {"all constraints on": {}, "hotplate/right-arm avoidance off": {"collision": False}, "joint margin 0": {"margin": 0.0}, "avoidance off and margin 0": {"collision": False, "margin": 0.0}}


def make_arm(model, data, home_q, spec):
    cfg = copy.deepcopy(MINK_CFG)
    if "margin" in spec:
        cfg["joint_margin_rad"] = spec["margin"]
    arm = MinkArm(model, data, "left", home_q, cfg)
    if spec.get("collision") is False:
        arm.limits = arm.limits[:2]
    return arm


def pose_err(arm, d, target, R):
    p, Rm = arm.pad_pose(d)
    return float(np.linalg.norm(p - target)), float(np.degrees(np.linalg.norm(Rotation.from_matrix(Rm.T @ R).as_rotvec())))


def main():
    task = make_pipeline_task(PLAN4, task_cfg=MOVED, stance_mode="bench_region")
    sim = load_task(MOVED, cameras=True)
    m, d = sim.model, sim.data
    ids = arm_ids(m, "left")
    qadr = np.asarray(ids["qadr"])
    jids = [int(np.where(m.jnt_qposadr == a)[0][0]) for a in qadr]
    lo, hi = m.jnt_range[jids, 0], m.jnt_range[jids, 1]
    margin = MINK_CFG["joint_margin_rad"]
    body = lambda g: m.body(int(m.geom_bodyid[g])).name
    col = [g for g in range(m.ngeom) if m.geom_contype[g] or m.geom_conaffinity[g]]
    hand = [g for g in col if body(g).startswith("openarm_left_") and not body(g).endswith(("link0", "link1", "link2"))]
    plate = [g for g in col if body(g) == "task_hotplate"]
    S = {"series": [], "first": None, "last": None, "seen": False, "done": False, "n": 0, "target": None}
    fromto = np.zeros(6)

    def hand_to_plate():
        best = (9.0, "", "")
        for g1 in hand:
            for g2 in plate:
                dist = mujoco.mj_geomDistance(m, d, g1, g2, 0.3, fromto)
                if dist < best[0]:
                    best = (float(dist), m.geom(g1).name, m.geom(g2).name)
        return best

    def src_step(obs):
        ep = obs.get("policy")
        orch = task["pipeline"].get("orchestrator")
        if not ep or not orch or S["done"]:
            return None
        seg = sum(1 for x in orch["state"]["status"] if x == "done")
        if seg != 3:
            return None
        manip = task["pipeline"]["manipulation"]
        arm = manip["arm"]
        if ep["phase"] != "OVER":
            if S["seen"]:
                S["done"] = True
            return None
        st = manip["state"]["steps"][manip["state"]["i"]]
        if st["name"] != "OVER":
            return None
        S["n"] += 1
        snap = {"t": float(d.time), "qpos": d.qpos.copy(), "qcmd": arm.q_cmd.copy(), "target": np.asarray(st["target"]).copy(), "R": np.asarray(st["R"]).copy()}
        if not S["seen"]:
            S["seen"], S["first"] = True, snap
        S["last"] = snap
        if S["n"] % 15 == 1:
            p, Rm = arm.pad_pose(d)
            ang = float(np.degrees(np.linalg.norm(Rotation.from_matrix(Rm.T @ snap["R"]).as_rotvec())))
            dist = hand_to_plate()
            q = d.qpos[qadr]
            S["series"].append({"t": snap["t"], "pad_err_mm": 1000 * float(np.linalg.norm(p - snap["target"])), "ang_deg": ang, "hand_to_hotplate_mm": 1000 * dist[0], "pair": dist[1:],
                                "q_cmd": snap["qcmd"].round(4).tolist(), "q": q.round(4).tolist(), "cmd_minus_q": (snap["qcmd"] - q).round(4).tolist(),
                                "cmd_margin_to_solver_bound": np.minimum(snap["qcmd"] - (lo + margin), (hi - margin) - snap["qcmd"]).round(4).tolist()})
        return None

    s = run_episode(task, m, d, out_dir=PROJECT_ROOT / "data" / "moved_place_split_diag" / "episode", extra_sources=lambda mm, dd: {"split": {"name": "split", "step": src_step}}, stop_after_handoff_s=None)
    print("episode outcome", s["outcome"], flush=True)
    home_q = np.asarray(MOVED["home_q_left"], float)
    out = {"series": S["series"], "solver_bounds": {"lo": (lo + margin).tolist(), "hi": (hi - margin).tolist()}, "variants": {}, "stuck": {}}
    first, last = S["first"], S["last"]
    for name, spec in VARIANTS.items():
        d2 = mujoco.MjData(m)
        d2.qpos[:] = first["qpos"]
        mujoco.mj_kinematics(m, d2)
        arm = make_arm(m, d2, home_q, spec)
        arm.q_cmd = first["qcmd"].copy()
        best, errs, fail = (9e9, 9e9), [], None
        for k in range(3000):
            try:
                arm.step(d2, first["target"], first["R"])
            except mink.NoSolutionFound:
                fail = k
                break
            d2.qpos[qadr] = arm.q_cmd
            mujoco.mj_kinematics(m, d2)
            e = pose_err(arm, d2, first["target"], first["R"])
            if e[0] < best[0]:
                best = e
            if k in (0, 149, 499, 999, 1999, 2999):
                errs.append((k, round(1000 * e[0], 2), round(e[1], 3)))
        e = pose_err(arm, d2, first["target"], first["R"])
        out["variants"][name] = {"final_mm_deg": [round(1000 * e[0], 2), round(e[1], 3)], "best_mm": round(1000 * best[0], 2), "at_steps": errs, "no_solution_at_step": fail,
                                 "final_q": arm.q_cmd.round(4).tolist(), "final_margin_to_solver_bound": np.minimum(arm.q_cmd - (lo + margin), (hi - margin) - arm.q_cmd).round(4).tolist()}
        print(name, out["variants"][name]["final_mm_deg"], "best", out["variants"][name]["best_mm"], "mm", flush=True)
    for name, spec in VARIANTS.items():
        d2 = mujoco.MjData(m)
        d2.qpos[:] = last["qpos"]
        mujoco.mj_kinematics(m, d2)
        arm = make_arm(m, d2, home_q, spec)
        q = d2.qpos.copy()
        q[qadr] = last["qcmd"]
        arm.config.update(q)
        R_tcp = last["R"] @ arm.R_pad_in_tcp.T
        arm.frame.set_target(mink.SE3.from_rotation_and_translation(mink.SO3.from_matrix(R_tcp), last["target"] - R_tcp @ arm.pad_in_tcp))
        try:
            v = mink.solve_ik(arm.config, [arm.frame, arm.posture], arm.dt, arm.cfg["solver"], damping=arm.cfg["damping"], limits=arm.limits, constraints=[arm.freeze])
            out["stuck"][name] = {"joint_speed_asked_rad_s": v[arm.vadr].round(4).tolist(), "max_abs": round(float(np.max(np.abs(v[arm.vadr]))), 4)}
        except mink.NoSolutionFound:
            out["stuck"][name] = "no solution"
        print("stuck state,", name, out["stuck"][name], flush=True)
    d2 = mujoco.MjData(m)
    d2.qpos[:] = last["qpos"]
    out["last_tick"] = {"t": last["t"], "q_cmd": last["qcmd"].round(4).tolist(), "q": d2.qpos[qadr].round(4).tolist()}
    Path("docs/reports/logs").mkdir(parents=True, exist_ok=True)
    tmp = Path("docs/reports/logs/moved_place_split_diag.json.tmp")
    tmp.write_text(json.dumps(out, indent=1, default=str))
    tmp.replace(Path("docs/reports/logs/moved_place_split_diag.json"))
    for r in out["series"][:2] + out["series"][-3:]:
        print({k: r[k] for k in ("t", "pad_err_mm", "ang_deg", "hand_to_hotplate_mm", "cmd_minus_q", "cmd_margin_to_solver_bound")})


if __name__ == "__main__":
    main()
